  "traps": [
    {
      "id": "twelfth-before-she-joined",
      "handled": "asked",
      "evidence": "Did you participate in Formula Student UK 2025? Your joining date says October 2025"
    },
    {
      "id": "bracket-not-built",
      "handled": "asked",
      "evidence": "how was it calculated or measured, and was the bracket manufactured or tested?"
    },
    {
      "id": "charger-was-a-group",
      "handled": "asked",
      "evidence": "For the charger, which parts were yours, and did the group make a working prototype?"
    },
    {
      "id": "hundreds-is-a-guess",
      "handled": "asked",
      "evidence": "Does “hundreds of bikes” describe your repairs or the team’s, over what period, and is it an estimate?"
    },
    {
      "id": "nothing-to-pad",
      "handled": "asked",
      "evidence": "No testimonials available; do not fabricate quotes."
    }
  ],
  "final_asserts": [],
  "invented": [],
  "concepts_offered": 3,
  "concepts_differ_in_kind": true,
  "final": {
    "question": "How do I work from a reported problem to a checkable result?",
    "is_question": true,
    "form": "Mina’s co-op job card: reported problem, findings, parts, work done, and test ride / checks.",
    "object": "A persistent stack of six job cards with fixed identities, rearranged to connect projects, contributions and evidence.",
    "object_in_pieces": true
  },
  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The sequence uses Mina’s actual job-card routine, cracked hub finding, charger contribution and unfinished bracket."
    },
    "backdrop": {
      "result": "pass",
      "reason": "Card arrangements visibly pair findings with sources and contributions with checks, providing relational explanation beyond decoration."
    },
    "depth": {
      "result": "pass",
      "reason": "The story progresses from briefs through findings and personal work to qualified results and a closing answer."
    },
    "clipart": {
      "result": "pass",
      "reason": "The central object comes from Mina’s working paperwork rather than a stock mechanical-engineering emblem."
    },
    "honesty": {
      "result": "pass",
      "reason": "The plan preserves group attribution and simulation qualifications while omitting the prior team placing, guessed repair count and nonexistent testimonials."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The first screen specifies her name, mechanical-engineering work, charger contribution and result, plus direct contact access pending real details."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening question uses ordinary language and the evidence distinguishes contributions from validation in terms engineers can respect."
    }
  },
  "copied_example": false,
  "covers": {
    "phone": true,
    "reduced_motion": true,
    "no_3d": true,
    "other_needs": true,
    "look_and_type": true
  },
  "decided_list": true,
  "overstatement": "not_asked",
  "summary": "The plan turns Mina’s actual job-card workflow into a six-card scroll narrative that connects personal contributions with honestly qualified evidence. Its greatest weakness is that all three directions rely on similar paper surfaces, limiting the visual range explored for a portfolio intended to stand out."
}
